card.content:
{% set agora = now() %}
{% set hora = agora.hour %}
{% set hoje = agora.date() %}
{% set ano = agora.year %}
{% set fim_de_semana = agora.weekday() in [5, 6] %}
{% set usuario = (user | default('') | lower) %}
{% set estado_clima = states('weather.forecast_casa') | lower %}
{% set temp = state_attr('weather.forecast_casa', 'temperature') | float(0) %}

{% if hora < 12 %}
  {% set saudacao = 'Bom dia' %}
  {% set emoji_periodo = '🌞' %}
{% elif hora < 18 %}
  {% set saudacao = 'Boa tarde' %}
  {% set emoji_periodo = '🌤️' %}
{% else %}
  {% set saudacao = 'Boa noite' %}
  {% set emoji_periodo = '🌙' %}
{% endif %}

{% if 'antonio' in usuario %}
  {% set frases_base = [
    'Bora fazer o dia render!',
    'Sua casa já está no esquema, chefe.',
    'Hoje promete, Antonio!',
    'Partiu colocar os planos em prática.'
  ] %}
{% elif 'renata' in usuario %}
  {% set frases_base = [
    'Que seu dia seja leve e lindo, Renata.',
    'Tudo pronto por aqui para você.',
    'Hoje vai ser um dia especial, Renata.',
    'Que hoje te traga boas surpresas.'
  ] %}
{% else %}
  {% set frases_base = [
    'Que seu dia seja leve e produtivo.',
    'Seguimos com foco e bom humor!',
    'Tudo certo por aqui para começar bem.'
  ] %}
{% endif %}

{% if fim_de_semana %}
  {% set frases_semana = [
    'Curta o fim de semana no seu ritmo.',
    'Dia perfeito para desacelerar e aproveitar.',
    'Fim de semana chegou: aproveite cada momento.'
  ] %}
{% else %}
  {% set frases_semana = [
    'Força na rotina: você dá conta!',
    'Mais um dia para conquistar muita coisa.',
    'Agenda cheia, mas vai dar certo.'
  ] %}
{% endif %}

{% set a = ano % 19 %}
{% set b = ano // 100 %}
{% set c = ano % 100 %}
{% set d = b // 4 %}
{% set e = b % 4 %}
{% set f = (b + 8) // 25 %}
{% set g = (b - f + 1) // 3 %}
{% set h = (19 * a + b - d - g + 15) % 30 %}
{% set i = c // 4 %}
{% set k = c % 4 %}
{% set l = (32 + 2 * e + 2 * i - h - k) % 7 %}
{% set m = (a + 11 * h + 22 * l) // 451 %}
{% set mes_pascoa = (h + l - 7 * m + 114) // 31 %}
{% set dia_pascoa = ((h + l - 7 * m + 114) % 31) + 1 %}
{% set pascoa = strptime(ano ~ '-' ~ mes_pascoa ~ '-' ~ dia_pascoa, '%Y-%m-%d').date() %}
{% set carnaval = pascoa - timedelta(days=47) %}
{% set sexta_santa = pascoa - timedelta(days=2) %}
{% set corpus_christi = pascoa + timedelta(days=60) %}

{% set feriados_fixos = {
  '01-01': 'Confraternização Universal',
  '04-21': 'Tiradentes',
  '05-01': 'Dia do Trabalho',
  '09-07': 'Independência do Brasil',
  '10-12': 'Nossa Senhora Aparecida',
  '11-02': 'Finados',
  '11-15': 'Proclamação da República',
  '12-25': 'Natal'
} %}

{% set mmdd = agora.strftime('%m-%d') %}
{% set nome_feriado = '' %}
{% if mmdd in feriados_fixos %}
  {% set nome_feriado = feriados_fixos[mmdd] %}
{% elif hoje == carnaval %}
  {% set nome_feriado = 'Carnaval' %}
{% elif hoje == sexta_santa %}
  {% set nome_feriado = 'Sexta-feira Santa' %}
{% elif hoje == pascoa %}
  {% set nome_feriado = 'Páscoa' %}
{% elif hoje == corpus_christi %}
  {% set nome_feriado = 'Corpus Christi' %}
{% endif %}

{% if nome_feriado != '' %}
  {% set frases_feriado = [
    'Hoje é ' ~ nome_feriado ~ '. Aproveite esse feriado! 🎉',
    'Feliz ' ~ nome_feriado ~ '! Que seja um dia especial.',
    'Aproveite o feriado de ' ~ nome_feriado ~ ' para recarregar as energias.'
  ] %}
{% else %}
  {% set frases_feriado = [] %}
{% endif %}

{% set limiar_chuva = 60 %}
{% set previsao = state_attr('weather.forecast_casa', 'forecast') %}
{% set chance_chuva = none %}
{% if previsao is iterable and (previsao | count) > 0 %}
  {% set p0 = previsao[0] %}
  {% if p0.precipitation_probability is defined %}
    {% set chance_chuva = p0.precipitation_probability | int(0) %}
  {% elif p0.precipitation is defined and (p0.precipitation | float(0)) > 0 %}
    {% set chance_chuva = 100 %}
  {% endif %}
{% endif %}

{% if chance_chuva is number and chance_chuva >= limiar_chuva %}
  {% set frase_clima = 'Chance de chuva em ' ~ chance_chuva ~ '%: melhor sair com guarda-chuva.' %}
{% elif estado_clima in ['rainy', 'pouring', 'lightning-rainy', 'hail', 'snowy-rainy'] %}
  {% set frase_clima = 'Tempo chuvoso agora: guarda-chuva pode salvar seu dia.' %}
{% elif temp >= 32 %}
  {% set frase_clima = 'Calor forte hoje: se hidrate bem e pegue leve no sol.' %}
{% elif temp >= 28 %}
  {% set frase_clima = 'Vai esquentar: água por perto e ventilação ajudam bastante.' %}
{% else %}
  {% set frase_clima = 'Clima agradável por agora, ótimo para seguir o plano.' %}
{% endif %}

{% set pool = frases_base + frases_semana + frases_feriado %}

# Olá {{ user }}
{{ saudacao }} {{ emoji_periodo }}
{{ pool | random }}
{{ frase_clima }}

card_mod.style:
:host {
  {% if states('sensor.dispositivos_offline')|int(0) > 0 %}
    --card-mod-icon-color: red;
    color: red;
  {% else %}
    --card-mod-icon-color: var(--disabled-text-color);
    color: var(--disabled-text-color);
  {% endif %}
}

:host {
  /* Estilo pela válvula: aberto=azul, fechado=vermelho, indefinido=cinza */
  {% if is_state('valve.casa_valvula_agua_z2m', 'open') %}
    --card-mod-icon-color: var(--primary-color);
    color: var(--primary-color);
  {% elif is_state('valve.casa_valvula_agua_z2m', 'closed') %}
    --card-mod-icon-color: red;
    color: red;
  {% else %}
    --card-mod-icon-color: var(--disabled-text-color);
    color: var(--disabled-text-color);
  {% endif %}
}

:host {
  /* Estilo pela válvula: aberto=azul, fechado=vermelho, indefinido=cinza */
  {% if is_state('valve.casa_valvula_gas_z2m', 'open') %}
    --card-mod-icon-color: var(--primary-color);
    color: var(--primary-color);
  {% elif is_state('valve.casa_valvula_gas_z2m', 'closed') %}
    --card-mod-icon-color: red;
    color: red;
  {% else %}
    --card-mod-icon-color: var(--disabled-text-color);
    color: var(--disabled-text-color);
  {% endif %}
}

:host {
  /* Define a cor do ícone com base no estado da válvula */
  {% if is_state('switch.caixa_d_agua_agua_pressurizada', 'on') %}
    --card-mod-icon-color: red;
  {% elif is_state('switch.caixa_d_agua_agua_pressurizada', 'off') %}
    --card-mod-icon-color: gray;
  {% else %}
    --card-mod-icon-color: black; /* Cor padrão para outros estados ou para depuração */
  {% endif %}
}

