filter.template:
{% set ns = namespace(items=[], seen=[]) %}
{% set domains = ['light', 'switch', 'climate', 'cover', 'fan', 'lock', 'vacuum', 'media_player'] %}
{% for d in domains %}
  {% for e in states[d] %}
    {% set eid = e.entity_id %}
    {% if e.state in ['unavailable', 'unknown']
         and 'ap_unifi_led' not in eid
         and 'alarme_indicacao' not in eid
         and 'termocirculador' not in eid
         and 'embaralhar' not in eid
         and 'repita' not in eid
         and 'firestick' not in eid
         and 'fire_tv' not in eid
         and 'camera' not in eid
         and 'choro' not in eid
         and 'alexa_app_for_pc' not in eid
         and 'usina_' not in eid
         and 'inkbird' not in eid
         and 'umidificador' not in eid
         and 'unifi_network' not in eid
         and 'grupo_de_som' not in eid
         and '_dispositivos' not in eid
         and 'announcements' not in eid
         and 'communications' not in eid %}
      {% set incluir = true %}
      {% if d == 'media_player' %}
        {% set incluir = ('echo' in eid) %}
      {% elif 'echo' in eid or 'alexa' in eid or 'mediaplayer' in eid %}
        {% set incluir = false %}
      {% endif %}
      {% if incluir %}
        {% set did = device_id(eid) %}
        {% set key = ('echo:' ~ (area_id(eid) or eid)) if (d == 'media_player' and 'echo' in eid) else (did if did else eid) %}
        {% if key not in ns.seen %}
          {% set ns.seen = ns.seen + [key] %}
          {% if did %}
            {% set dname = device_attr(did, 'name_by_user') or device_attr(did, 'name') or e.name %}
          {% else %}
            {% set dname = e.name %}
          {% endif %}
          {% set area = area_name(eid) %}
          {% set label = (area ~ ' — ' ~ dname) if area else dname %}
          {% set ns.items = ns.items + [{'entity': eid, 'name': label}] %}
        {% endif %}
      {% endif %}
    {% endif %}
  {% endfor %}
{% endfor %}
{{ ns.items | tojson }}

custom_card_andyblac_room.label:
[[[
  const formatVal = (src) => {
    const eid = typeof src === 'string' ? src : src?.entity_id;
    if (!eid || !states[eid]) return null;
    const st = states[eid].state;
    if (st === 'unknown' || st === 'unavailable' || st === null) return null;
    const dc = states[eid].attributes?.device_class;
    const unit = states[eid].attributes?.unit_of_measurement;
    const num = Number(st);
    const hasNum = Number.isFinite(num);
    let val;
    if (dc === 'temperature' || unit === '°C') val = `${hasNum ? num.toFixed(1) : st}°C`;
    else if (dc === 'humidity' || unit === '%') val = `${hasNum ? num.toFixed(0) : st}%`;
    else val = `${st}`;
    const prefix = typeof src === 'object' ? src?.prefix : null;
    return prefix ? `${prefix}: ${val}` : val;
  };
  const line1 = [variables?.sensor_label_1, variables?.sensor_label_2, variables?.sensor_label_3].map(formatVal).filter(Boolean).join(' | ');
  const line2 = [variables?.sensor_label_4, variables?.sensor_label_5, variables?.sensor_label_6].map(formatVal).filter(Boolean).join(' | ');
  return [line1, line2].filter(Boolean).join('<br/>');
]]]

