    const style = `<style>@keyframes clip{0%{visibility:visible;clip-path:inset(0 0 45% 0);}100%{clip-path:inset(0 0 0 0);}}.shower-on{animation:clip 1.4s ease-out infinite;transform-origin:center;visibility:hidden;will-change:transform;}.shower-static{transform-origin:center;will-change:transform;}</style>`;
    const showerIcon = showerActive
      ? `<svg viewBox="0 0 24 24" style="width:78px;height:78px;color:${iconColor};">${style}<g class="shower-on">${path}</g></svg>`
