[[[
  const eid = (entity?.entity_id || '').toLowerCase();
  const icon = (variables?.sensor_1?.icon || '').toLowerCase();
  let c = variables?.sensor_1?.active_color ||  '#f59e0b';
  if (icon.includes('bug') || eid.includes('repelente')) c = '#a16207';
