  else if (eid.startsWith('cover.') || icon.includes('shutter') || icon.includes('curtain') || icon.includes('storefront')) c = '#a855f7';
  else if (icon.includes('window') || icon.includes('door') || eid.includes('janela') || eid.includes('porta')) c = '#f97316';
