  const icon = (variables?.sensor_3?.icon || '').toLowerCase();
  let c = '#f59e0b';
  if (icon.includes('bug') || eid.includes('repelente')) c = '#a16207';
  else if (eid.startsWith('climate.') || icon.includes('air-conditioner')) c = '#38bdf8';
  else if (eid.startsWith('cover.') || icon.includes('shutter') || icon.includes('curtain') || icon.includes('storefront')) c = '#a855f7';
  else if (icon.includes('window') || icon.includes('door') || eid.includes('janela') || eid.includes('porta')) c = '#f97316';
  else if (icon.includes('motion') || eid.includes('occupancy') || eid.includes('presenca')) c = '#22c55e';
  else if (eid.startsWith('media_player.') || icon.includes('television') || icon.includes('speaker')) c = '#3b82f6';
  else if (icon.includes('shower') || eid.includes('chuveiro')) c = '#06b6d4';
  return `0 0 0 1px color-mix(in srgb, ${c} 65%, transparent), 0 3px 10px color-mix(in srgb, ${c} 30%, transparent)`;
]]]

