card.extra_styles:
@keyframes camera-scan {
  0% { transform: perspective(90px) rotateY(0deg); }
  50% { transform: perspective(90px) rotateY(-180deg); }
  100% { transform: perspective(90px) rotateY(0deg); }
}

custom_card_andyblac_room.extra_styles:
@keyframes ha-washer-spin {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}
@keyframes ha-dishwasher-shake {
  0%, 100% { transform: translateX(0) rotate(0deg); }
  20% { transform: translateX(-1px) rotate(-7deg); }
  40% { transform: translateX(1px) rotate(7deg); }
  60% { transform: translateX(-1px) rotate(-5deg); }
  80% { transform: translateX(1px) rotate(5deg); }
}
